ALTER TABLE "Employee" ADD COLUMN IF NOT EXISTS "admissionDate" TIMESTAMP(3), ADD COLUMN IF NOT EXISTS "dismissalDate" TIMESTAMP(3), ADD COLUMN IF NOT EXISTS "employmentNature" TEXT, ADD COLUMN IF NOT EXISTS "socialSecurityRegime" TEXT NOT NULL DEFAULT 'RGPS', ADD COLUMN IF NOT EXISTS "pisPasep" TEXT, ADD COLUMN IF NOT EXISTS "bankCode" TEXT, ADD COLUMN IF NOT EXISTS "bankAgency" TEXT, ADD COLUMN IF NOT EXISTS "bankAccount" TEXT;
ALTER TABLE "Payroll" ADD COLUMN IF NOT EXISTS "grossValue" DOUBLE PRECISION NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS "discountValue" DOUBLE PRECISION NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS "calculatedAt" TIMESTAMP(3), ADD COLUMN IF NOT EXISTS "closedAt" TIMESTAMP(3), ADD COLUMN IF NOT EXISTS "closedBy" TEXT, ADD COLUMN IF NOT EXISTS "snapshot" JSONB, ADD COLUMN IF NOT EXISTS "snapshotHash" TEXT;
CREATE TABLE IF NOT EXISTS "PayrollVariable" ("id" TEXT NOT NULL, "payrollId" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "kind" TEXT NOT NULL, "quantity" DOUBLE PRECISION NOT NULL DEFAULT 0, "value" DOUBLE PRECISION NOT NULL DEFAULT 0, "note" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PayrollVariable_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "PayrollVariable_payrollId_employeeId_idx" ON "PayrollVariable"("payrollId", "employeeId");
ALTER TABLE "PayrollVariable" ADD CONSTRAINT "PayrollVariable_payrollId_fkey" FOREIGN KEY ("payrollId") REFERENCES "Payroll"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PayrollVariable" ADD CONSTRAINT "PayrollVariable_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE IF NOT EXISTS "PayrollAuditLog" ("id" TEXT NOT NULL, "payrollId" TEXT NOT NULL, "action" TEXT NOT NULL, "actor" TEXT, "reason" TEXT, "details" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PayrollAuditLog_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "PayrollAuditLog_payrollId_idx" ON "PayrollAuditLog"("payrollId");
ALTER TABLE "PayrollAuditLog" ADD CONSTRAINT "PayrollAuditLog_payrollId_fkey" FOREIGN KEY ("payrollId") REFERENCES "Payroll"("id") ON DELETE CASCADE ON UPDATE CASCADE;
